question:
Tập hợp nghiệm của phương trình bậc nhất hai ẩn nào sau đây được biểu diễn hình học là đường thẳng $d$ như hình dưới đây?
\begin{center}
\begin{tikzpicture}[scale=0.8]
\draw[->] (-2,0) -- (6,0) node[right] {$x$};
\draw[->] (0,-2) -- (0,3) node[above] {$y$};
\foreach \x in {-1,1,2,3,4,5} \draw (\x,0.1) -- (\x,-0.1) node[below] {$\x$};
\foreach \y in {-1,1,2} \draw (0.1,\y) -- (-0.1,\y) node[left] {$\y$};
\node[below left] at (0,0) {$O$};
\draw[thick, mainblue, domain=-1.5:4.5] plot (\x, {-0.5*\x + 1.5}) node[above right] {$d$};
\fill (-1,2) circle (2pt) node[above] {$N$};
\fill (3,0) circle (2pt) node[above right] {$B$};
\draw[dashed] (-1,0) -- (-1,2) -- (0,2);
\end{tikzpicture}
\end{center}

Tập hợp nghiệm của phương trình bậc nhất hai ẩn nào sau đây được biểu diễn hình học là đường thẳng $d$ như hình dưới đây?
\begin{center}
\begin{tikzpicture}[scale=0.8]
\draw[->] (-4,0) -- (4,0) node[right] {$x$};
\draw[->] (0,-4) -- (0,2) node[above] {$y$};
\foreach \x in {-3,-2,-1,1,2,3} \draw (\x,0.1) -- (\x,-0.1) node[below] {$\x$};
\foreach \y in {-3,-2,-1,1} \draw (0.1,\y) -- (-0.1,\y) node[left] {$\y$};
\node[below left] at (0,0) {$O$};
\draw[thick, mainblue] (-3.5,-2) -- (3.5,-2) node[above right] {$d$};
\fill (0,-2) circle (2pt) node[above right] {$A$};
\end{tikzpicture}
\end{center}

Tập hợp nghiệm của phương trình bậc nhất hai ẩn nào sau đây được biểu diễn hình học là đường thẳng $d$ như hình dưới đây?
\begin{center}
\begin{tikzpicture}[scale=0.8]
\draw[->] (-3,0) -- (6,0) node[right] {$x$};
\draw[->] (0,-3) -- (0,3) node[above] {$y$};
\foreach \x in {-2,-1,1,2,3,4,5} \draw (\x,0.1) -- (\x,-0.1) node[below] {$\x$};
\foreach \y in {-2,-1,1,2} \draw (0.1,\y) -- (-0.1,\y) node[left] {$\y$};
\node[below left] at (0,0) {$O$};
\draw[thick, mainblue] (3,-2.5) -- (3,2.5) node[right] {$d$};
\fill (3,0) circle (2pt) node[above right] {$B$};
\end{tikzpicture}
\end{center}
